// Boss sprites as base64 data URIs (WebP, lossy quality 85, 284x357 —
// same resolution as the PNG sources, no downscale).
// The PNG sources live in public/assets/IronWarden.png and
// public/assets/Bombardier.png, but snapshot pushes carry text only,
// so the shipped game loads the art from here instead of the files.
// WebP was chosen over the original PNG data URIs for bundle size:
// lossless WebP saved ~35% of this module's gzip, lossy q85 saves ~80%
// with no visible artifacts at display size (alpha channel bit-exact).
// Regenerate with PIL:
//   python3 -c "from PIL import Image; import io, base64; \
//     im = Image.open('public/assets/<Name>.png'); buf = io.BytesIO(); \
//     im.save(buf, 'WEBP', quality=85, method=6); \
//     print(base64.b64encode(buf.getvalue()).decode())"
// and paste the output after 'data:image/webp;base64,'.
export const IRON_WARDEN_DATA_URI = 'data:image/webp;base64,' + "";

export const BOMBARDIER_DATA_URI = 'data:image/webp;base64,' + "";
